const p = msg.payload;
if (typeof p !== 'object' || p === null || typeof p.g !== 'string' || typeof p.conf !== 'number') {
    node.warn('Dropped malformed gesture event on ' + msg.topic);
    return null;
}
const parts = String(msg.topic || '').split('/');
const device = parts[1] || 'gesture1';
const fields = {
    conf: Number(p.conf),
    count: 1
};
const tags = {
    device: String(device),
    mode: String(p.mode || 'edge'),
    gesture: String(p.g)
};
msg.payload = [fields, tags];
return msg;

const m = msg.payload;
if (typeof m !== 'object' || m === null || typeof m.mode !== 'string') {
    node.warn('Dropped malformed metrics message on ' + msg.topic);
    return null;
}
const parts = String(msg.topic || '').split('/');
const device = parts[1] || 'gesture1';
const lat = typeof m.lat_ms === 'number' ? m.lat_ms : -1;
const isTimeout = (m.error === 'timeout' || lat < 0) ? 1 : 0;
const fields = {
    seq: Number(m.seq || 0),
    bytes: Number(m.bytes || 0),
    conf: Number(m.conf || 0),
    timeout: isTimeout
};
if (lat >= 0) {
    fields.lat_ms = Number(lat);
}
const tags = {
    device: String(device),
    mode: String(m.mode),
    gesture: String(m.g || 'timeout')
};
msg.payload = [fields, tags];
return msg;

const s = String(msg.payload || '').trim().toLowerCase();
const parts = String(msg.topic || '').split('/');
const device = parts[1] || 'gesture1';
const online = s === 'online' ? 1 : 0;
msg.payload = [{ online: online }, { device: String(device), state: s || 'offline' }];
return msg;
